import { aiLogicOrigin } from "../api";
import { FirebaseError, getErrStatus } from "../error";
import * as backend from "../deploy/functions/backend";
import * as events from "../functions/events";

const API_VERSION = "v1beta";

/** An HTTP client for the AI Logic API. */
export const client = new Client({
  urlPrefix: aiLogicOrigin(),
  apiVersion: API_VERSION,
});

type Endpoint = backend.Endpoint & backend.BlockingTriggered;

/** Maps an AI Logic blocking event type to its API trigger id. */
const TRIGGER_ID_BY_EVENT: Record<string, string> = {
  [events.v2.AI_LOGIC_BEFORE_GENERATE_CONTENT]: "before-generate-content",
  [events.v2.AI_LOGIC_AFTER_GENERATE_CONTENT]: "after-generate-content",
};

/** Returns the trigger id for an AI Logic blocking endpoint. */
function triggerId(endpoint: Endpoint): string {
  const id = TRIGGER_ID_BY_EVENT[endpoint.blockingTrigger.eventType];
  if (!id) {
    throw new FirebaseError(
      `Received invalid AI Logic blocking trigger event type ${endpoint.blockingTrigger.eventType}`,
    );
  }
  return id;
}

/**
 * Returns the API location for an AI Logic blocking endpoint. Regional triggers
 * (those with the regionalWebhook option set) use the endpoint region; global
 * triggers use "global".
 */
function locationId(endpoint: Endpoint): string {
  return endpoint.blockingTrigger.options?.regionalWebhook === true ? endpoint.region : "global";
}

function requestBody(endpoint: Endpoint): { cloudFunction: { id: string; locationId: string } } {
  return {
    cloudFunction: {
      id: endpoint.id,
      locationId: endpoint.region,
    },
  };
}

/**
 * Creates a new AI Logic blocking trigger via POST. If the POST fails with an
 * HTTP 409 (conflict), falls back to a PATCH that updates the existing trigger.
 * For any other POST failure, the error is thrown without calling PATCH.
 * @param endpoint the AI Logic blocking endpoint to register
 */
export async function upsertBlockingFunction(endpoint: Endpoint): Promise<void> {
  const location = locationId(endpoint);
  const id = triggerId(endpoint);
  const body = requestBody(endpoint);
  try {
    await client.post(`projects/${endpoint.project}/locations/${location}/triggers`, body, {
      queryParams: { triggerId: id, validateOnly: "false" },
    });
  } catch (err: unknown) {
    if (getErrStatus(err) !== 409) {
      throw err;
    }
    await client.patch(
      `projects/${endpoint.project}/locations/${location}/triggers/${id}`,
      body,
      {
        queryParams: { allowMissing: "false", validateOnly: "false" },
      },
    );
  }
}

/**
 * Deletes an AI Logic blocking trigger. Uses allowMissing so the deletion is
 * idempotent.
 * @param endpoint the AI Logic blocking endpoint to unregister
 */
export async function deleteBlockingFunction(endpoint: Endpoint): Promise<void> {
  const location = locationId(endpoint);
  const id = triggerId(endpoint);
  await client.delete(`projects/${endpoint.project}/locations/${location}/triggers/${id}`, {
    queryParams: { allowMissing: "true", validateOnly: "false" },
  });
}
